from math import log2

def dfs(s, p, l):
	stack = [s]
	p[s] = s
	l[s] = 1
	while stack:
		x = stack.pop()
		for y in Tree[x]:
			if not l[y]:
				p[y] = x
				l[y] = l[x] + 1
				stack.append(y)

def searchLCA(x, y):
	if l[x] > l[y]:
		(x, y) = (y, x)
	d = l[y] - l[x]
	if d != 0:
		for i in range(MAX2 - 1, -1, -1):
			if d >= 1 << i:
				d -= 1 << i
				y = pp[y][i]
	if x == y:
		return x + 1
	for i in range(MAX2 - 1, -1, -1):
		if pp[x][i] != pp[y][i]:
			x = pp[x][i]
			y = pp[y][i]
	return pp[x][0] + 1
N = int(input())
Tree = [[] for _ in range(N)]
for _ in range(N - 1):
	(x, y) = map(int, input().split())
	Tree[x - 1].append(y - 1)
	Tree[y - 1].append(x - 1)
p = [None] * N
l = [None] * N
dfs(0, p, l)
MAX2 = int(log2(max(l))) + 1
pp = [[None] * MAX2 for _ in range(N)]
for i in range(N):
	pp[i][0] = p[i]
for j in range(1, MAX2):
	for i in range(N):
		pp[i][j] = pp[pp[i][j - 1]][j - 1]
Q = int(input())
for _ in range(Q):
	(r, x, y) = map(int, input().split())
	rr = searchLCA(x - 1, y - 1)
	xx = searchLCA(r - 1, y - 1)
	yy = searchLCA(x - 1, r - 1)
	if xx == yy:
		print(rr)
	elif xx == rr:
		print(yy)
	else:
		print(xx)
